{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Metoclopramide, a high-transfer analogue with a dimethoxybenzamide/amino/amide motif, has a human oral bioavailability of approximately 77%, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Donepezil, a high-transfer analogue sharing a dimethoxyphenyl and basic amine system, has an absolute oral bioavailability of 100% in humans, strongly supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Suvorexant, a high-transfer analogue containing a piperazine-amide heteroaromatic core, has a mean oral bioavailability of 82% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "GSK1322322, a high-transfer analogue with dimethoxyphenyl and piperazine features, has an absolute oral bioavailability of 57% in the fasted state, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Delavirdine, a high-transfer analogue with a piperazine amide, has an oral bioavailability of 85% in patients, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Valbenazine, a high-transfer analogue with a dimethoxytetrahydroisoquinoline core, has an absolute oral bioavailability of approximately 49% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Piritrexim, a high-transfer dimethoxyphenyl analogue, showed an absolute oral bioavailability of 23% in one patient, the lower end of its range but still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Papaverine, a high-transfer dimethoxyisoquinoline analogue, had an absolute bioavailability of 22% from a sustained-release formulation, still meeting the F >= 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values from 22% to 100%, with most in the 46-100% range; none fall below the 20% threshold. The query's prazosin-like structure is consistent with these well-absorbed, moderately first-pass-metabolized drugs, so F >= 20% is strongly supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself is present; the prediction relies on high-transfer analogues.",
    "Some analogue bioavailability values are formulation- or dose-dependent, but all remain above the 20% threshold."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "metoclopramide"
    }
  ],
  "revision_action": "initial"
}

